mapper.select:
select ccb.* from (select ccr.*, (select meaning from sys_code_value_b_v where code = 'CHANGE_REQ_STATUS' and code_value = ccr.status ) status_n, (select su.DESCRIPTION from sys_user su where su.USER_ID = ccr.change_req_user_id) change_req_user_id_n, (select wm_concat(hbm1.bp_name) from hls_bp_master hbm1,con_contract_bp ccb where cc.contract_id = ccb.contract_id and hbm1.BP_ID=ccb.bp_id and ccb.bp_category='TENANT' ) bp_id_tenant_n, ( select meaning from sys_code_value_b_v where code = 'CON.CONTRACT_CHANGE_TYPE' and code_value = ccr.change_type ) change_type_n, cc.contract_number, cc.contract_name, pp.project_number, cc.finance_amount, (select hdc.description from hls_document_category hdc where hdc.document_category = cc.document_category) document_category_n, nvl(cc.inception_of_lease,cc.lease_start_date) inception_of_lease, cc.FACTORY_ID, cc.MANUFACTURER_ID, cc.bp_id_vender, cc.lease_channel, cc.division, (select hbm.bp_name from hls_bp_master hbm where cc.FACTORY_ID = hbm.BP_ID) FACTORY_ID_n, (select hbm.bp_name from hls_bp_master hbm where cc.MANUFACTURER_ID = hbm.BP_ID) MANUFACTURER_ID_n, (select hb.bp_name from hls_bp_master hb where hb.bp_id = cc.bp_id_vender) bp_id_vender_n, (SELECT t1.description FROM hls_lease_channel t1 WHERE t1.lease_channel = cc.lease_channel) as lease_channel_n, (select hd.description from hls_division hd where hd.division=cc.division) division_n, (select hbt.description from hls_business_type hbt where hbt.business_type = cc.business_type and hbt.document_category = 'CONTRACT') business_type_n, (case when (select count(cash.cashflow_id) from con_contract_cashflow cash where cash.contract_id = cc.contract_id and trunc(cash.due_date) = trunc(sysdate) and cash.cf_direction = 'INFLOW' and cash.cf_status = 'RELEASE' and cash.due_amount - nvl(cash.received_amount, 0) > 0) > 0 then '是' else '否' end) as current_overdue_status, cc.irr, cc.price_list, (select description as value_name from hls_price_list p where cc.price_list=p.price_list) price_list_n,
(select max(ccc.times) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_item = 1) times, (select fe.name from fnd_employee fe where fe.employee_id = cc.employee_id) employee_id_n from prj_project pp, con_contract_change_req ccr, con_contract cc where cc.project_id = pp.PROJECT_ID and ccr.contract_id = cc.contract_id /*没有取消申请*/ and ccr.status != 'UNDO' /*排除大单合同变更数据*/ and ccr.change_type != 'PARTIAL_PREPAYMENT'
and pp.PROJECT_NUMBER like concat(concat('%',#{projectNumber}),'%')
and #{financeAmountFrom} <= cc.finance_amount
and #{financeAmountTo} >= cc.finance_amount
and #{division} = cc.division
and cc.document_category = #{documentCategory}
and cc.created_by = #{createdBy}
and #{creationDateFrom} <= cc.creation_date
and #{creationDateTo} >= cc.creation_date
AND cc.contract_number like concat(concat('%',#{contractNumber}),'%')
AND cc.contract_name like concat(concat('%',#{contractName}),'%')
and cc.contract_status = #{contractStatus}
and cc.business_type = #{businessType}
and cc.contract_id = #{contractId}
and ccr.change_req_id = #{changeReqId}
order by ccr.change_req_id desc ) ccb
and ccb.bp_id_tenant_n like concat(concat('%',#{bpIdTenantN}),'%')

select ccb.* from (select ccr.*, (select meaning from sys_code_value_b_v where code = 'CHANGE_REQ_STATUS' and code_value = ccr.status ) status_n, (select su.DESCRIPTION from sys_user su where su.USER_ID = ccr.change_req_user_id) change_req_user_id_n, (select hbm1.bp_name from hls_bp_master hbm1 where hbm1.BP_ID=cc.tenant_id ) bp_id_tenant_n, ( select meaning from sys_code_value_b_v where code = 'CON.CONTRACT_CHANGE_TYPE_PART' and code_value = ccr.change_type ) change_type_n, cc.contract_number, cc.contract_name, pp.project_number, cc.finance_amount, (select hdc.description from hls_document_category hdc where hdc.document_category = cc.document_category) document_category_n, nvl(cc.inception_of_lease,cc.lease_start_date) inception_of_lease, cc.FACTORY_ID, cc.MANUFACTURER_ID, cc.bp_id_vender, cc.lease_channel, cc.division, (select hbm.bp_name from hls_bp_master hbm where cc.FACTORY_ID = hbm.BP_ID) FACTORY_ID_n, (select hbm.bp_name from hls_bp_master hbm where cc.MANUFACTURER_ID = hbm.BP_ID) MANUFACTURER_ID_n, (select hb.bp_name from hls_bp_master hb where hb.bp_id = cc.bp_id_vender) bp_id_vender_n, (SELECT t1.description FROM hls_lease_channel t1 WHERE t1.lease_channel = cc.lease_channel) as lease_channel_n, (select hd.description from hls_division hd where hd.division=cc.division) division_n, (select hbt.description from hls_business_type hbt where hbt.business_type = cc.business_type and hbt.document_category = 'CONTRACT') business_type_n, (case when (select count(cash.cashflow_id) from con_contract_cashflow cash where cash.contract_id = cc.contract_id and trunc(cash.due_date) = trunc(sysdate) and cash.cf_direction = 'INFLOW' and cash.cf_status = 'RELEASE' and cash.due_amount - nvl(cash.received_amount, 0) > 0) > 0 then '是' else '否' end) as current_overdue_status, cc.irr, cc.xirr, cc.price_list, (select description as value_name from hls_price_list p where cc.price_list=p.price_list) price_list_n,
(select max(ccc.times) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_item = 1) times, (select fe.name from fnd_employee fe where fe.employee_id = cc.employee_id) employee_id_n from prj_project pp, con_contract_change_req ccr, con_contract cc where cc.project_id = pp.PROJECT_ID and ccr.contract_id = cc.contract_id AND pp.data_class = 'VIRTUAL_CON' AND pp.data_type = 'NORMAL' AND pp.contract_name IS NOT NULL AND pp.contract_number IS NOT NULL /*没有取消申请*/ and ccr.status != 'UNDO' /*大单合同变更数据*/ and ccr.change_type = 'PARTIAL_PREPAYMENT'
and ccr.status = #{status}
and cc.tenant_id in (select bp.bp_id from hls_bp_master bp where bp.bp_name like concat(concat('%',#{bpName}),'%'))
and #{changeReqDateFrom} <= to_char(ccr.change_req_date,'yyyy-mm-dd')
and #{changeReqDateTo} >= to_char(ccr.change_req_date,'yyyy-mm-dd')
and pp.PROJECT_NUMBER like concat(concat('%',#{projectNumber}),'%')
and #{financeAmountFrom} <= cc.finance_amount
and #{financeAmountTo} >= cc.finance_amount
and #{division} = cc.division
and cc.document_category = #{documentCategory}
and cc.created_by = #{createdBy}
and #{creationDateFrom} <= cc.creation_date
and #{creationDateTo} >= cc.creation_date
AND cc.contract_number like concat(concat('%',#{contractNumber}),'%')
AND cc.contract_name like concat(concat('%',#{contractName}),'%')
and cc.contract_status = #{contractStatus}
and cc.business_type = #{businessType}
and cc.contract_id = #{contractId}
and ccr.change_req_id = #{changeReqId}
order by ccr.change_req_id desc ) ccb
and ccb.bp_id_tenant_n like concat(concat('%',#{bpIdTenantN}),'%')

select ccr.*, concat(concat(cc.contract_number,'-'),(select CONTRACT_SEQ from prj_quotation where quotation_id = ccr.quotation_id)) quotation_id_n, (select meaning from sys_code_value_b_v where code = 'HLS_WFL_STATUS' and code_value = ccr.status ) status_n, cc.contract_number, hbm.bp_name bp_id_tenant_n, bpt.description bp_type_n, cc.contract_name, su.DESCRIPTION change_req_user_id_n, ( select meaning from sys_code_value_b_v where code = 'CON.CONTRACT_CHANGE_TYPE' and code_value = ccr.change_type ) change_type_n, pp.project_number, (select hd.description from hls_division hd where hd.division = cc.division) division_n, cc.finance_amount, (select hbt.description from hls_business_type hbt where hbt.business_type = cc.business_type and hbt.document_category = 'CONTRACT') business_type_n, (select hdc.description from hls_document_category hdc where hdc.document_category = cc.document_category) document_category_n, cc.inception_of_lease from prj_project pp, con_contract_change_req ccr join con_contract cc on ccr.contract_id = cc.contract_id left join hls_bp_master hbm on cc.TENANT_ID = hbm.BP_ID left join hls_bp_type bpt on bpt.bp_category = hbm.BP_CATEGORY and bpt.bp_type = hbm.BP_TYPE left join sys_user su on su.USER_ID = ccr.change_req_user_id where 1=1 and cc.project_id = pp.PROJECT_ID
and pp.PROJECT_NUMBER like concat(concat('%',#{projectNumber}),'%')
and hbm.BP_TYPE like concat(concat('%',#{bpType}),'%')
and #{financeAmountFrom} <= cc.finance_amount
and #{financeAmountTo} >= cc.finance_amount
and #{division} = cc.division
and cc.document_category = #{documentCategory}
and cc.created_by = #{createdBy}
and #{creationDateFrom} <= cc.creation_date
and #{creationDateTo} >= cc.creation_date
AND cc.contract_number like concat(concat('%',#{contractNumber}),'%')
AND cc.contract_name like concat(concat('%',#{contractName}),'%')
and cc.contract_status = #{contractStatus}
and cc.business_type = #{businessType}
and cc.contract_id = #{contractId}
and ccr.change_req_id = #{changeReqId}
order by change_req_id asc

select
/*提前结清款项*/ (nvl(v1.overdue_amount,0) + nvl(v1.outstanding_principal,0) + nvl(v1.period_interest,0) + nvl(v1.penalty_interest,0) + nvl(v1.nominal_price,0) )pre_amount,
v1.* from (select
/*期间利息*/ round(case when v.manufacturer_user = 'YX-TH' then nvl(((to_number(trunc(#{dueDate}) - trunc(v.last_due_date)))/v.days * v.interest),0) else (nvl((v.outstanding_principal*v.int_rate/360*(to_number( trunc(#{dueDate}) - trunc(v.last_due_date) ))),0)) end,2) period_interest, /*期间批复利息*/ nvl((v.outstanding_principal*v.int_rate_reply_tmp/360*(to_number( trunc(#{dueDate}) - trunc(v.last_due_date) ))),0) period_reply_interest,
v.* from ( select
/*提前结清期数*/ ( select min(ccc.times) from con_contract_cashflow ccc where ccc.cf_item = 1 and ccc.contract_id = cc.contract_id and trunc(ccc.due_date) >= trunc(#{dueDate}) )times, /*逾期租金*/ (select nvl(sum(nvl(ccc.due_amount, 0) - nvl(ccc.received_amount, 0)), 0) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_item = 1 and ccc.write_off_flag != 'FULL' and trunc(ccc.due_date) < trunc(#{dueDate})) overdue_amount, /*剩余本金*/ nvl(( select nvl(ccc.outstanding_principal,0) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and (ccc.cf_item = 1 or ccc.cf_item = 0) and trunc(ccc.due_date) < trunc(#{dueDate}) and ccc.times = ( select max(c.times) from con_contract_cashflow c where c.cf_item in (0,1) and c.contract_id = cc.contract_id and trunc(c.due_date) < trunc(#{dueDate}) ) and rownum = 1 ), 0)outstanding_principal, ( select case ccc.times when 0 then cc.inception_of_lease else ccc.due_date end from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and (ccc.cf_item = 1 or ccc.cf_item = 0) and trunc(ccc.due_date) < trunc(#{dueDate}) and ccc.times = ( select min(c.times)-1 from con_contract_cashflow c where c.cf_item = 1 and c.contract_id = cc.contract_id and trunc(c.due_date) >= trunc(#{dueDate}) ) and rownum = 1 )last_due_date, /*返利款金额*/ ( select nvl(sum(nvl(ccc.due_amount,0) - nvl(ccc.received_amount,0)),0) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_item = 60 and trunc(ccc.due_date) < trunc(#{dueDate}) )reply_amount, /*贴息金额*/ ( select nvl(sum(nvl(ccc.due_amount,0) - nvl(ccc.received_amount,0)),0) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_item = 61 and trunc(ccc.due_date) < trunc(#{dueDate}) )discount_amount, /*提前结清日所在区间天数*/ (((select trunc(ccc.due_date) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.times = ( select min(ccc.times) from con_contract_cashflow ccc where ccc.cf_item = 1 and ccc.contract_id = cc.contract_id and trunc(ccc.due_date) >= trunc(#{dueDate})) and ccc.cf_item = 1 ))- ( select case ccc.times when 0 then cc.inception_of_lease else ccc.due_date end from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and (ccc.cf_item = 1 or ccc.cf_item = 0) and trunc(ccc.due_date) < trunc(#{dueDate}) and ccc.times = ( select min(c.times)-1 from con_contract_cashflow c where c.cf_item = 1 and c.contract_id = cc.contract_id and trunc(c.due_date) >= trunc(#{dueDate}) ) and rownum = 1 ))as days, /*结清前提前结清期数利息 */ (select ccc.interest from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.times = ( select min(ccc.times) from con_contract_cashflow ccc where ccc.cf_item = 1 and ccc.contract_id = cc.contract_id and trunc(ccc.due_date) >= trunc(#{dueDate})) and ccc.cf_item = 1) as interest,
cc.contract_id, cc.int_rate, (select pq.irr from prj_quotation pq where pq.source_document_id = cc.contract_id and pq.source_document_category = 'CONTRACT' and pq.enabled_flag = 'Y' and rownum = 1) irr, (select pq.int_rate_reply from prj_quotation pq where pq.source_document_id = cc.contract_id and pq.source_document_category = 'CONTRACT' and pq.enabled_flag = 'Y' and rownum = 1) int_rate_reply_tmp, /*保证金*/ nvl((select (nvl(sum(t.transaction_amount),0) - nvl(sum(t.WRITE_OFF_AMOUNT), 0) - nvl(sum(t.BLOCK_AMOUNT), 0)) FROM csh_transaction t WHERE t.contract_id = cc.contract_id AND t.transaction_type = 'DEPOSIT' AND t.reversed_flag = 'N' AND NOT EXISTS (SELECT 1 FROM csh_deposit_deduct_req_hd cddrh WHERE cddrh.transaction_id = t.transaction_id AND cddrh.req_status IN ('NEW', 'REJECTED', 'APPROVING'))),0) deposit, /*罚息金额*/ nvl((select sum(nvl(ccc.due_amount, 0) - nvl(ccc.received_amount, 0)) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_item = 9), 0) penalty_interest, /*名义货价*/ (select nvl(sum(nvl(ccc.due_amount,0) - nvl(ccc.received_amount,0) ),0) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_item = 8) nominal_price,cc.division as division,pp.manufacturer_user as manufacturer_user, cccr.status from con_contract cc,con_contract_change_req cccr,prj_project pp where cc.contract_id = cccr.contract_id and cc.contract_number = pp.project_number and cccr.change_req_id = #{changeReqId} )v) v1
